 1|-- ===========================================================================
 2|-- 02_dynamic_tables / 05_signals_fast.sql
 3|-- ===========================================================================
 4|-- Every rule conf/detection.yml assigns to signals_fast, one UNION ALL branch
 5|-- each, from sql/rules/<rule_id>.sql. Built:
 6|{% for rule_id, spec in rule | dictsort if spec.dynamic_table == "signals_fast" %}
 7|--   {{ rule_id }} v{{ spec.version }}
 8|{% endfor %}
 9|--
10|-- One row per (rule, party, window): recomputed on every refresh, so the same
11|-- logical signal reappears each time. signal_business_key is what the router
12|-- MERGEs on, which is what makes that harmless (GAP-11).
13|--
14|-- rule_version and severity are NOT carried here; the router takes both from
15|-- RULE_DEFINITION, the registry the policy stage governs.
16|-- ===========================================================================
17|{% from "02_dynamic_tables/_macros.sql" import target_lag %}
18|
19|CREATE OR ALTER DYNAMIC TABLE {{ fq.curated }}.{{ dt.signals_fast.name }}
20|    TARGET_LAG = {{ target_lag(dt.signals_fast) }}
21|    WAREHOUSE = {{ wh.pipeline }}
22|    REFRESH_MODE = INCREMENTAL
23|    COMMENT = 'Rule firings at party-window grain, keyed by signal_business_key. Routed by ROUTE_SIGNALS.'
24|AS
25|{% for rule_id, spec in rule | dictsort if spec.dynamic_table == "signals_fast" %}
26|{% include "rules/" ~ rule_id ~ ".sql" %}
27|{{ "UNION ALL" if not loop.last else "" }}
28|{% endfor %}
29|;
30|
